using System.Collections;
using System.Diagnostics;
using System.IO;
using System.Reflection;
using System.Text;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;
using System.Windows.Threading;
using RenoDXMfgUnlocker;

internal static class Rc1SettingsChecks
{
    public static IEnumerable<(string Name,Action Run)> All(){
        yield return("rc1 settings category placement covers every reviewed control exactly once",Placement);
        yield return("rc1 settings category navigation filters existing row instances with no writes",Navigation);
        yield return("rc1 settings pending edits and shared Save state survive every category",Pending);
        yield return("rc1 settings shared cross-category plan saves both INIs and restores exact bytes",SaveRestore);
        yield return("rc1 settings Discard resets pending values across hidden categories",Discard);
        yield return("rc1 settings Reload drops pending edits and rechecks real addon identity",Reload);
        yield return("rc1 settings single generation selector synchronizes keys and locks hidden NVIDIA options",Generation);
        yield return("rc1 settings old and unknown versions retain capability gates in every category",Versions);
        yield return("rc1 settings shared stale-file and process guards preserve source bytes",Guards);
        yield return("rc1 settings one scroller and shared footer stay outside filtered content",Structure);
        yield return("rc1 settings category localization switches immediately without losing edits",Localization);
        yield return("rc1 settings unshown templates bind without errors in each category",Bindings);
    }
    private const BindingFlags Flags=BindingFlags.NonPublic|BindingFlags.Instance;
    private static object? Get(object o,string field)=>o.GetType().GetField(field,Flags)!.GetValue(o);
    private static void Set(object o,string field,object? value)=>o.GetType().GetField(field,Flags)!.SetValue(o,value);
    private static object? Call(object o,string method,params object?[] args)=>o.GetType().GetMethod(method,Flags)!.Invoke(o,args);
    private static void Check(bool value,string reason){if(!value)throw new Exception(reason);}
    private static void Reject(Action action){try{action();}catch(Exception e)when(e is IOException or InvalidOperationException or InvalidDataException){return;}throw new Exception("Expected refusal");}
    private static string Temp(){var path=Path.Combine(Path.GetTempPath(),"RenoDX-RC1",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(path);return path;}
    internal sealed class Fixture:IDisposable
    {
        public readonly MainWindow Window=new();
        public readonly string Root=Temp();
        public readonly List<(MfgUnlockSettingsService Service,MfgUnlockSettingsSnapshot Snapshot)> Docs=[];
        public readonly string Version;
        public Fixture(string version="1.8.0.0", MfgDynamicSettingsCatalog? catalog=null){
            Version=version;var exe=Path.Combine(Root,"Own-"+Guid.NewGuid().ToString("N")+".exe");File.Copy(Environment.ProcessPath!,exe);
            // Synthetic configuration/UI identity only. This fixture does not claim to be a genuine addon.
            var addon=Path.Combine(Root,"renodx-mfgunlock.addon64");File.WriteAllText(addon,"synthetic fixture; never executed");
            File.WriteAllText(Path.Combine(Root,"ReShade.ini"),"; retain main\r\n[Other]\r\nCustom=9 ; keep\r\n[RenoDX.MFGUnlock]\r\nEnabled=1\r\n",new UTF8Encoding(true));
            File.WriteAllText(Path.Combine(Root,"MFGAdaUnlock.ini"),"; retain runtime\r\n[Other]\r\nCustom=yes\r\n[Backend]\r\nSelected=DLSSG\r\n[DLSSG]\r\nXmxGenerator=0 ; keep\r\n",new UTF8Encoding(true));
            Set(Window,"selectedExe",exe);Set(Window,"selectedGameRoot",Root);Set(Window,"mfgSettingsExePath",exe);Set(Window,"mfgSettingsAddonHash",MfgUnlockSettingsService.GetSha256(File.ReadAllBytes(addon)));
            var rowType=typeof(MainWindow).GetNestedType("MfgUnlockSettingRow",BindingFlags.NonPublic)!;var docType=typeof(MainWindow).GetNestedType("MfgSettingsDocument",BindingFlags.NonPublic)!;
            foreach(var (service,field) in new[]{(new MfgUnlockSettingsService(catalog:catalog),"mfgSettingRows"),(new MfgUnlockSettingsService(true,catalog),"xeMfgSettingRows")}){
                var snapshot=service.Load(Path.Combine(Root,service.ConfigFileName),Root,version);Docs.Add((service,snapshot));var rows=(IList)Get(Window,field)!;
                foreach(var s in snapshot.Settings)
                {
                    var row=Activator.CreateInstance(rowType,[s.Definition,s.RawValue??"default",s.ProposedValue,snapshot.IsSupportedAddonVersion&&s.IsValid,(Action)(()=>Call(Window,"UpdateMfgSettingsButtons"))])!;
                    rowType.GetProperty("State")!.SetValue(row,s);
                    rows.Add(row);
                }
                ((IList)Get(Window,"mfgSettingsDocuments")!).Add(Activator.CreateInstance(docType,[service,snapshot,rows])!);
            }
            Set(Window,"mfgSettingsSnapshot",Docs[0].Snapshot);Call(Window,"UpdateMfgSettingsButtons");
        }
        public IEnumerable<object> Rows=>((IEnumerable)Get(Window,"mfgSettingRows")!).Cast<object>().Concat(((IEnumerable)Get(Window,"xeMfgSettingRows")!).Cast<object>());
        public object Row(string key)=>Rows.Single(r=>Definition(r).Key==key);
        public string? Value(string key)=>(string?)Row(key).GetType().GetProperty("ProposedValue")!.GetValue(Row(key));
        public void Edit(string key,string value)=>Row(key).GetType().GetProperty("ProposedValue")!.SetValue(Row(key),value);
        public void Select(MfgSettingsCategory category)=>Call(Window,"SelectMfgCategory",category);
        public object[] Visible()=>new[]{"MfgSettingsItemsControl","XeMfgSettingsItemsControl"}.SelectMany(n=>((ItemsControl)Window.FindName(n)).Items.Cast<object>()).ToArray();
        public (MfgUnlockSettingsService Service,MfgUnlockSettingsSnapshot Snapshot,Dictionary<string,string> Changes)[] Edits()=>((IEnumerable)Call(Window,"PendingMfgEdits")!).Cast<object>().Select(e=>{
            var doc=e.GetType().GetField("Item1")!.GetValue(e)!;return ((MfgUnlockSettingsService)doc.GetType().GetProperty("Service")!.GetValue(doc)!,(MfgUnlockSettingsSnapshot)doc.GetType().GetProperty("Snapshot")!.GetValue(doc)!,(Dictionary<string,string>)e.GetType().GetField("Item2")!.GetValue(e)!);
        }).ToArray();
        public Dictionary<string,string> Hashes()=>Directory.GetFiles(Root).ToDictionary(p=>Path.GetFileName(p)!,p=>MfgUnlockSettingsService.GetSha256(File.ReadAllBytes(p)))!;
        public void Dispose()=>Window.Close();
    }
    private static MfgUnlockSettingDefinition Definition(object row)=>(MfgUnlockSettingDefinition)row.GetType().GetProperty("Definition")!.GetValue(row)!;
    private static void Placement(){foreach(var v in new[]{"1.6.0.0","1.7.0.0","1.8.0.0","Unknown"}){var all=new[]{new MfgUnlockSettingsService(),new MfgUnlockSettingsService(true)}.SelectMany(s=>s.DefinitionsFor(v)).ToArray();Check(all.Select(d=>d.Key).Distinct().Count()==all.Length,"Schema duplicate");foreach(var d in all)Check(Enum.GetValues<MfgSettingsCategory>().Count(c=>c==MfgSettingsLayout.CategoryFor(d.Key))==1,"Unreachable category");Check(all.Where(d=>MfgSettingsLayout.IsMethodKey(d.Key)).All(d=>MfgSettingsLayout.CategoryFor(d.Key)==MfgSettingsCategory.General),"Mode keys not represented by General selector");}}
    private static void Navigation()=>WpfCheckHost.Run(()=>{using var f=new Fixture();Check((MfgSettingsCategory)Get(f.Window,"mfgCategory")! == MfgSettingsCategory.General,"Not General by default");var hashes=f.Hashes();var seen=new List<string>();foreach(var c in Enum.GetValues<MfgSettingsCategory>()){((Button)f.Window.FindName("Mfg"+c+"Tab")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check((MfgSettingsCategory)Get(f.Window,"mfgCategory")! == c,"Tab not functional");var rows=f.Visible();Check(rows.All(r=>MfgSettingsLayout.CategoryFor(Definition(r).Key)==c&&!MfgSettingsLayout.IsMethodKey(Definition(r).Key)),"Wrong category or duplicate raw selector");seen.AddRange(rows.Select(r=>Definition(r).Key));Check(((StackPanel)f.Window.FindName("GenerationModePanel")).Visibility==(c==MfgSettingsCategory.General?Visibility.Visible:Visibility.Collapsed),"Selector leaks between categories");}Check(seen.Count==13&&seen.Distinct().Count()==13,"Lost or duplicated editable setting");Check(hashes.All(p=>f.Hashes()[p.Key]==p.Value),"Navigation wrote a file");});
    private static void Pending()=>WpfCheckHost.Run(()=>{using var f=new Fixture();var rows=f.Rows.ToArray();var hashes=f.Hashes();f.Edit("Enabled","0");f.Edit("RuntimeSelectionMode","1");f.Edit("ForceBorderless","1");foreach(var c in Enum.GetValues<MfgSettingsCategory>()){f.Select(c);Materialize(f.Window);Check(f.Value("Enabled")=="0"&&f.Value("RuntimeSelectionMode")=="1"&&f.Value("ForceBorderless")=="1","Pending changes lost");Check(f.Rows.SequenceEqual(rows),"Tab rebuilt settings state");Check(((Button)f.Window.FindName("MfgSettingsSaveButton")).IsEnabled&&((TextBlock)f.Window.FindName("MfgRestartStatusText")).Text.Contains("Unsaved"),"Shared dirty state lost");Check(f.Edits().Sum(d=>d.Changes.Count)==3,"Save sees only selected category");}Check(hashes.All(p=>f.Hashes()[p.Key]==p.Value),"Pending edits wrote files");});
    private static void SaveRestore()=>WpfCheckHost.Run(()=>{using var f=new Fixture();var original=Directory.GetFiles(f.Root).ToDictionary(p=>p,p=>File.ReadAllBytes(p));f.Edit("Enabled","0");f.Edit("RuntimeSelectionMode","1");f.Edit("ForceBorderless","1");f.Select(MfgSettingsCategory.Other);var files=f.Edits().Select(e=>e.Service.PrepareTransaction(e.Snapshot,e.Changes,()=>true)).ToArray();Check(files.Length==2&&original.All(p=>File.ReadAllBytes(p.Key).SequenceEqual(p.Value)),"Shared plan omitted a file or wrote before confirmation");var backup=new BackupRestoreService(Temp());var result=backup.ExecuteAsync(f.Root,files).GetAwaiter().GetResult();foreach(var (service,_) in f.Docs){var reloaded=service.Load(Path.Combine(f.Root,service.ConfigFileName),f.Root,f.Version);Check(reloaded.HasUtf8Bom&&reloaded.Newline=="\r\n","Encoding/newline changed");}Check(File.ReadAllText(Path.Combine(f.Root,"ReShade.ini")).Contains("Custom=9 ; keep")&&File.ReadAllText(Path.Combine(f.Root,"MFGAdaUnlock.ini")).Contains("XmxGenerator=0 ; keep"),"Unchanged data lost");backup.RestoreAsync(f.Root,result.TransactionId).GetAwaiter().GetResult();Check(original.All(p=>File.ReadAllBytes(p.Key).SequenceEqual(p.Value)),"Restore lost exact original bytes");});
    private static void Discard()=>WpfCheckHost.Run(()=>{using var f=new Fixture();var hashes=f.Hashes();f.Edit("Enabled","0");f.Edit("RuntimeSelectionMode","1");f.Edit("ForceBorderless","1");Call(f.Window,"SelectGenerationMethod","XMX");f.Select(MfgSettingsCategory.Advanced);((Button)f.Window.FindName("MfgSettingsDiscardButton")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(f.Value("Enabled")=="1"&&f.Value("RuntimeSelectionMode")=="0"&&f.Value("ForceBorderless")=="0"&&f.Value("XmxGenerator")=="0"&&f.Edits().Length==0,"Discard only reset visible controls");Check(!((Button)f.Window.FindName("MfgSettingsSaveButton")).IsEnabled&&hashes.All(p=>f.Hashes()[p.Key]==p.Value),"Discard wrote or left dirty state");});
    private static void Reload()=>WpfCheckHost.Run(()=>{using var f=new Fixture();f.Edit("Enabled","0");f.Edit("ForceBorderless","1");f.Select(MfgSettingsCategory.Other);var hashes=f.Hashes();var task=(Task)Call(f.Window,"LoadMfgSettingsAsync")!;var until=Stopwatch.StartNew();while(!task.IsCompleted&&until.Elapsed<TimeSpan.FromSeconds(8)){Dispatcher.CurrentDispatcher.Invoke(()=>{},DispatcherPriority.Background);Thread.Sleep(1);}Check(task.IsCompleted,"Reload timed out");task.GetAwaiter().GetResult();Check(f.Value("Enabled")=="1"&&!f.Rows.Any(r=>(bool)r.GetType().GetProperty("CanEdit")!.GetValue(r)!),"Reload kept proposed value or trusted synthetic addon identity");Check((MfgSettingsCategory)Get(f.Window,"mfgCategory")! == MfgSettingsCategory.Other&&f.Edits().Length==0,"Reload lost category or kept pending edits");Check(hashes.All(p=>f.Hashes()[p.Key]==p.Value),"Reload wrote files");});
    private static void Generation()=>WpfCheckHost.Run(()=>{using var f=new Fixture();var panel=(StackPanel)f.Window.FindName("GenerationModePanel");var modes=((WrapPanel)panel.Children[0]).Children.Cast<Button>().ToArray();foreach(var mode in new[]{"XMX","XeMFG","DLSSG"}){f.Select(MfgSettingsCategory.General);modes.Single(b=>(string)b.Tag==mode).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(f.Value("Selected")== (mode=="XeMFG"?"XeMFG":"DLSSG")&&f.Value("XmxGenerator")== (mode=="XMX"?"1":"0"),"Mode keys inconsistent");f.Select(MfgSettingsCategory.Advanced);foreach(var r in f.Rows.Where(r=>MfgUnlockSettingsService.NvidiaGeneratorOnly(Definition(r).Key)))Check((bool)r.GetType().GetProperty("CanEdit")!.GetValue(r)! == (mode!="XMX"),"Hidden NVIDIA restriction lost");Check(ReferenceEquals(modes[0],((WrapPanel)panel.Children[0]).Children[0]),"Method buttons recreated and lose keyboard focus");}Check(!f.Visible().Any(r=>MfgSettingsLayout.IsMethodKey(Definition(r).Key)),"Second method editor exposed");});
    private static void Versions()=>WpfCheckHost.Run(()=>{foreach(var v in new[]{"1.6.0.0","1.7.0.0","1.8.0-beta.1","Unknown"}){using var f=new Fixture(v);var seen=new HashSet<string>();foreach(var c in Enum.GetValues<MfgSettingsCategory>()){f.Select(c);foreach(var row in f.Visible())seen.Add(Definition(row).Key);Check(((StackPanel)f.Window.FindName("GenerationModePanel")).Visibility==Visibility.Collapsed,"180 selector leaked to "+v);}Check(seen.SetEquals(f.Rows.Select(r=>Definition(r).Key)),"Older settings unreachable");if(v is "1.8.0-beta.1" or "Unknown")Check(f.Rows.All(r=>!(bool)r.GetType().GetProperty("CanEdit")!.GetValue(r)!),"Future version unlocked");}});
    private static void Guards()=>WpfCheckHost.Run(()=>{using var f=new Fixture();f.Edit("Enabled","0");f.Select(MfgSettingsCategory.Other);var edits=f.Edits();Reject(()=>edits[0].Service.PrepareTransaction(edits[0].Snapshot,edits[0].Changes,()=>false));File.AppendAllText(Path.Combine(f.Root,"ReShade.ini"),"; external edit\r\n");var bytes=File.ReadAllBytes(Path.Combine(f.Root,"ReShade.ini"));Reject(()=>edits[0].Service.PrepareTransaction(edits[0].Snapshot,edits[0].Changes,()=>true));Check(File.ReadAllBytes(Path.Combine(f.Root,"ReShade.ini")).SequenceEqual(bytes),"Guard changed data");});
    private static IEnumerable<DependencyObject> Tree(DependencyObject parent){foreach(var c in LogicalTreeHelper.GetChildren(parent).OfType<DependencyObject>()){yield return c;foreach(var n in Tree(c))yield return n;}}
    private static void Structure()=>WpfCheckHost.Run(()=>{using var f=new Fixture();var page=(Grid)f.Window.FindName("MfgSettingsPage");var footer=(Grid)f.Window.FindName("MfgSettingsFooter");var scroll=(ScrollViewer)f.Window.FindName("MfgSettingsScroll");Check(ReferenceEquals(footer.Parent,page)&&Grid.GetRow(footer)>Grid.GetRow(scroll)&&Tree(page).OfType<ScrollViewer>().Count()==1,"Nested scrolling or footer moves with content");foreach(var c in Enum.GetValues<MfgSettingsCategory>()){f.Select(c);Check(footer.Visibility==Visibility.Visible&&Tree(footer).OfType<Button>().Count()==3,"Shared workflow not available");}f.Select((MfgSettingsCategory)99);Check((MfgSettingsCategory)Get(f.Window,"mfgCategory")! == MfgSettingsCategory.Other,"Invalid category accepted");});
    private static void Localization()=>WpfCheckHost.Run(()=>{using var f=new Fixture();f.Edit("Enabled","0");var l=LocalizedPresentation.Language;try{Check(l.ValidateCatalogs().Count==0,"Catalog mismatch");foreach(var culture in UiLocalization.Cultures){l.SetCulture(culture,false);foreach(var c in Enum.GetValues<MfgSettingsCategory>()){f.Select(c);Check(((Button)f.Window.FindName("Mfg"+c+"Tab")).Content as string==l.Lookup(c.ToString()),"Tab language did not update");var heading=((TextBlock)f.Window.FindName("MfgCategoryDescription")).Text;Check(culture=="en-US"||!heading.StartsWith("Common options")&&!heading.StartsWith("NVIDIA quality")&&!heading.StartsWith("Presentation workarounds"),"New description English fallback");}Check(f.Value("Enabled")=="0"&&f.Value("Selected")=="DLSSG","Language changed values");Check(TechnicalVersionDisplay.Format("1,8,0,0")=="1.8.0.0","Version culture changed");}}finally{l.SetCulture("en-US",false);}});
    private static void Materialize(MainWindow window){var page=(FrameworkElement)window.FindName("MfgSettingsPage");page.Visibility=Visibility.Visible;page.Measure(new Size(1040,700));page.Arrange(new Rect(0,0,1040,700));page.UpdateLayout();Dispatcher.CurrentDispatcher.Invoke(()=>{},DispatcherPriority.Background);}
    private static void Bindings()=>WpfCheckHost.Run(()=>{using var f=new Fixture();var output=new StringWriter();var listener=new TextWriterTraceListener(output);System.Diagnostics.PresentationTraceSources.DataBindingSource.Listeners.Add(listener);try{var page=(FrameworkElement)f.Window.FindName("MfgSettingsPage");page.Visibility=Visibility.Visible;foreach(var c in Enum.GetValues<MfgSettingsCategory>()){f.Select(c);page.Measure(new Size(1040,700));page.Arrange(new Rect(0,0,1040,700));page.UpdateLayout();Dispatcher.CurrentDispatcher.Invoke(()=>{},DispatcherPriority.Background);Check(((ItemsControl)f.Window.FindName("MfgSettingsItemsControl")).ItemContainerGenerator.ContainerFromIndex(0) is not null,"Setting templates were not materialized");}listener.Flush();Check(!output.ToString().Contains("Error:"),"Binding errors: "+output);}finally{System.Diagnostics.PresentationTraceSources.DataBindingSource.Listeners.Remove(listener);}});
}
